//! Parity tests for `gpt_sovits_text::english` against golden fixtures
//! generated by `parity/english/gen_fixtures.py`.
//!
//! Every field is compared exactly, including the exception type and message
//! where Python raises.

use std::collections::BTreeMap;

use gpt_sovits_text::en_normalization;
use gpt_sovits_text::english::{
  self, _g2p, Error, G2pDict, g2p, get_dict, get_namedict, hot_reload_hot, read_dict,
  read_dict_new, replace_consecutive_punctuation, replace_phs, text_normalize,
};
use serde_json::{Value, json};

const DICT: &str = include_str!("fixtures/english/dict.json");
const TEXTS: &str = include_str!("fixtures/english/texts.jsonl");
const QRYWORD: &str = include_str!("fixtures/english/qryword.jsonl");
const FUNCS: &str = include_str!("fixtures/english/funcs.jsonl");

/// Inputs whose Rust output is known to differ from Python. They must be
/// documented in `parity/english/README.md`; currently
/// there are none.
const KNOWN_MISMATCHES: &[&str] = &[];

fn lines(s: &str) -> impl Iterator<Item = Value> + '_ {
  s.lines().map(|l| serde_json::from_str(l).unwrap())
}

fn to_json<T: serde::Serialize>(r: Result<T, Error>) -> Value {
  match r {
    Ok(v) => json!({ "o": v }),
    Err(e) => json!({ "e": [e.name(), e.message()] }),
  }
}

fn norm_json(r: &Result<String, en_normalization::Error>) -> Value {
  match r {
    Ok(v) => json!({ "o": v }),
    Err(e) => json!({ "e": [e.name(), e.message()] }),
  }
}

/// FNV-1a 64 digest of a dictionary, as `digest` in the generator computes
/// it.
fn digest(d: &G2pDict) -> String {
  let mut h: u64 = 0xcbf29ce484222325;
  let sorted: BTreeMap<&String, &Vec<Vec<String>>> = d.iter().collect();
  for (key, prons) in sorted {
    let value = prons
      .iter()
      .map(|p| p.join("\x1f"))
      .collect::<Vec<_>>()
      .join("\x1e");
    let s = format!("{key}\x1d{value}\x1c");
    for b in s.bytes() {
      h ^= u64::from(b);
      h = h.wrapping_mul(0x100000001b3);
    }
  }
  format!("{h:016x}")
}

fn check_summary(name: &str, d: &G2pDict, expected: &Value) {
  assert_eq!(
    d.len() as u64,
    expected["len"].as_u64().unwrap(),
    "{name}: len"
  );
  for (k, v) in expected["sample"].as_object().unwrap() {
    assert_eq!(d.get(k).map(|p| json!(p)), Some(v.clone()), "{name}: {k:?}");
  }
  assert_eq!(
    digest(d),
    expected["digest"].as_str().unwrap(),
    "{name}: digest"
  );
}

#[test]
fn dictionaries() {
  let expected: Value = serde_json::from_str(DICT).unwrap();
  assert_eq!(to_json(read_dict()), expected["read_dict"]);
  check_summary(
    "read_dict_new",
    &read_dict_new().unwrap(),
    &expected["read_dict_new"],
  );
  assert_eq!(
    json!(hot_reload_hot(G2pDict::new())),
    expected["hot_reload_hot_empty"]
  );
  check_summary("get_dict", &get_dict().unwrap(), &expected["get_dict"]);
  check_summary("cmu", &_g2p().cmu, &expected["cmu"]);
  check_summary("namedict", &get_namedict(), &expected["namedict"]);
  check_summary("_g2p.namedict", &_g2p().namedict, &expected["namedict"]);

  let h = &_g2p().homograph2features;
  assert_eq!(
    h.len() as u64,
    expected["homograph2features_len"].as_u64().unwrap()
  );
  for (k, v) in expected["homograph2features"].as_object().unwrap() {
    assert_eq!(json!(h[k]), *v, "homograph2features[{k:?}]");
  }
}

#[test]
fn texts() {
  let mut n = 0;
  let mut per_src: BTreeMap<String, (usize, usize)> = BTreeMap::new();
  let mut mismatches: Vec<String> = Vec::new();
  for case in lines(TEXTS) {
    n += 1;
    let text = case["i"].as_str().unwrap();
    let src = case["src"].as_str().unwrap().to_string();
    let norm_r = text_normalize(text);
    let mut got = json!({ "i": text, "norm": norm_json(&norm_r), "src": src });
    match &norm_r {
      Ok(norm) => {
        got["g2p"] = to_json(g2p(norm));
        if case.get("call").is_some() {
          got["call"] = to_json(_g2p().__call__(norm));
        }
      }
      Err(_) => got["g2p"] = Value::Null,
    }
    if case.get("raw").is_some() {
      got["raw"] = to_json(g2p(text));
    }
    let entry = per_src.entry(src).or_default();
    entry.0 += 1;
    if got == case {
      entry.1 += 1;
    } else if !KNOWN_MISMATCHES.contains(&text) {
      mismatches.push(format!("expected {case}\n     got {got}"));
    }
  }
  for (src, (cases, matched)) in &per_src {
    eprintln!("texts/{src}: {matched}/{cases}");
  }
  assert!(n >= 6000, "only {n} cases");
  assert!(
    mismatches.is_empty(),
    "{} of {n} texts differ:\n{}",
    mismatches.len(),
    mismatches[..mismatches.len().min(20)].join("\n")
  );
}

#[test]
fn qryword() {
  let g = _g2p();
  let mut n = 0;
  let mut mismatches = Vec::new();
  for case in lines(QRYWORD) {
    n += 1;
    let word = case["i"].as_str().unwrap();
    let mut got = to_json(g.qryword(word));
    got["i"] = json!(word);
    if got != case && !KNOWN_MISMATCHES.contains(&word) {
      mismatches.push(format!("expected {case}\n     got {got}"));
    }
  }
  eprintln!("qryword: {}/{n}", n - mismatches.len());
  assert!(
    mismatches.is_empty(),
    "{} of {n} words differ:\n{}",
    mismatches.len(),
    mismatches[..mismatches.len().min(20)].join("\n")
  );
}

#[test]
fn funcs() {
  let mut n = 0;
  for case in lines(FUNCS) {
    n += 1;
    let f = case["f"].as_str().unwrap();
    let got = match f {
      "replace_consecutive_punctuation" => {
        json!(replace_consecutive_punctuation(case["i"].as_str().unwrap()))
      }
      "replace_phs" => {
        let phs: Vec<String> = serde_json::from_value(case["i"].clone()).unwrap();
        json!(replace_phs(&phs))
      }
      _ => panic!("unknown function {f}"),
    };
    assert_eq!(got, case["o"], "{f}({})", case["i"]);
  }
  eprintln!("funcs: {n}/{n}");
}

#[test]
fn constants() {
  assert_eq!(english::REP_MAP.len(), 5);
  assert_eq!(english::ARPA.len(), 71);
}
